bash: mkdir -p /tmp/kleetest && cd /tmp/kleetest && cat > t.c <<'EOF'
#include <klee/klee.h>
#include <assert.h>
int main(void) {
  int a;
  klee_make_symbolic(&a, sizeof(a), "a");
  if (a > 10) {
    assert(a != 12);   /* KLEE must find the a == 12 counterexample */
  }
  return 0;
}
EOF
export PATH=/usr/local/bin:$PATH CPATH=/usr/local/include
