summary:
bash: rm -rf /tmp/final && mkdir -p /tmp/final && cd /tmp/final
env -i HOME=/root PATH=/usr/bin:/bin /bin/bash --noprofile --norc -c '
source ~/.bashrc
cat > prog.c <<EOF
#include <klee/klee.h>
#include <assert.h>
int main(void){
  unsigned char buf[3];
  klee_make_symbolic(buf, sizeof buf, "buf");
  if (buf[0] == 0x41 && buf[1] == 0x42 && buf[2] == 0x43) assert(0);
  return 0;
}
EOF
echo "== compile with plain clang (default=16) via CPATH =="
clang -emit-llvm -c -g -O0 prog.c -o prog.bc && echo "compiled ok"
echo "== run klee (STP) =="
klee --output-dir=kout prog.bc 2>&1 | grep -E "solver|SAT solver|done: generated"
echo "== solved input =="
ktest-tool kout/test*.ktest 2>/dev/null | grep -E "buf :|text:" | tail -3
'

